static const char s_week[7][4]={"SUN","MON","TUE","WED","THU","FRI","SAT"};
static const uint8_t s_star[4][2]={{6,58},{34,54},{118,6},{122,61}};
static uint32_t s_inM[4][SCENE_DIG_H],s_onM[4][SCENE_DIG_H];
static int8_t s_cache[4]={-1,-1,-1,-1};
static int32_t SegmentDistance(int32_t px,int32_t py,const DigitPoint *a,const DigitPoint *b)
{
    int32_t ax=a->x*16,ay=a->y*16,dx=(b->x-a->x)*16,dy=(b->y-a->y)*16,len=dx*dx+dy*dy,dot=(px-ax)*dx+(py-ay)*dy,qx,qy;
    if(!len) { qx=ax; qy=ay; } else {
        if(dot<0) { dot=0; } if(dot>len) { dot=len; } qx=ax+dx*dot/len; qy=ay+dy*dot/len;
    }
    dx=px-qx; dy=py-qy; return dx*dx+dy*dy;
}
static void Digit_Build(uint8_t slot,uint8_t value)
{
    int32_t x,y,d,best;
    uint8_t k;
    const DigitPath *p=&s_paths[value];
    for(y=0;y<SCENE_DIG_H;y++) {
        s_inM[slot][y]=s_onM[slot][y]=0u;
        for(x=0;x<SCENE_DIG_W;x++) {
            best=0x7FFFFFFFL;
            for(k=0u;k+1u<p->n;k++) { d=SegmentDistance((x-2)*16,(y-2)*16,&p->p[k],&p->p[k+1u]); if(d<best) { best=d; } }
            if(best<=1600) { s_inM[slot][y] |= 1uL<<x; if(best>=576 || best<=64) { s_onM[slot][y] |= 1uL<<x; } }
        }
    }
}
static void Digits_Update(uint8_t h,uint8_t m)
{
    uint8_t w[4],i;
    w[0]=(uint8_t)(h/10u); w[1]=(uint8_t)(h%10u); w[2]=(uint8_t)(m/10u); w[3]=(uint8_t)(m%10u);
    for(i=0u;i<4u;i++) { if(s_cache[i]!=(int8_t)w[i]) { Digit_Build(i,w[i]); s_cache[i]=(int8_t)w[i]; } }
}
static uint8_t TimeArea(int32_t u,int32_t v)
{
    if(u>=SCENE_HOUR_X-2 && u<SCENE_HOUR_X+SCENE_DIG_PITCH+SCENE_DIG_W+2 && v>=SCENE_HOUR_Y-2 && v<SCENE_HOUR_Y+SCENE_DIG_H+2) { return 1u; }
    if(u>=SCENE_MIN_X-2 && u<SCENE_MIN_X+SCENE_DIG_PITCH+SCENE_DIG_W+2 && v>=SCENE_MIN_Y-2 && v<SCENE_MIN_Y+SCENE_DIG_H+2) { return 1u; }
    if(u>=SCENE_SEC_X-2 && u<SCENE_SEC_X+14 && v>=SCENE_SEC_Y-2 && v<SCENE_SEC_Y+9) { return 1u; } return 0u;
}
static int32_t DigitPixel(uint8_t slot,int32_t x,int32_t y)
{
    if(x<0 || y<0 || x>=SCENE_DIG_W || y>=SCENE_DIG_H) { return -1; }
    if(!(s_inM[slot][y] & (1uL<<x))) { return -1; } return (s_onM[slot][y] & (1uL<<x))?1:0;
}
/* Black-hole stroke digit font (s_paths) reused for the moving hour label.
 * The distance field keeps its double white tube strokes; the black gaps stay
 * transparent so no dial pixel is erased. The inverse black-hole transform
 * adds its exact ~12.6 degree lean; ink and 1px guard must be black before paint. */
static uint8_t  s_hv[2]={200u,200u};
static uint32_t s_hOn[2][18];   /* white stroke pixels only; gaps remain transparent */
#define HOUR_MOVE_INTERVAL_MS 100u
static int16_t s_hourX=64,s_hourY=32;
static uint32_t s_hourMoveAt=0u;
static uint8_t s_hourPosValid=0u,s_hourMoveClockValid=0u,s_hourLastDrawn=0u,s_hourLastRadius=0u;
#if defined(FW_SIMULATOR)
static uint32_t s_hourClearTests=0u;
static uint8_t s_hourBase[OLED_H/8][OLED_W];
#endif
static int32_t Stroke_Dist8(int32_t px8,int32_t py8,const DigitPoint *a,const DigitPoint *b)
{
    int32_t ax=a->x*6,ay=a->y*6,dx=(b->x-a->x)*6,dy=(b->y-a->y)*6,len=dx*dx+dy*dy,dot,qx,qy;
    if(!len) { qx=ax; qy=ay; } else {
        dot=(px8-ax)*dx+(py8-ay)*dy;
        if(dot<0) { dot=0; } if(dot>len) { dot=len; }
        qx=ax+dx*dot/len; qy=ay+dy*dot/len;
    }
    dx=px8-qx; dy=py8-qy; return dx*dx+dy*dy;
}
static void Stroke_Build(uint8_t slot,uint8_t value)
{
    int32_t x,y,best,d;
    uint8_t k;
    const DigitPath *p=&s_paths[value];
    for(y=-2;y<16;y++) {
        s_hOn[slot][y+2]=0u;
        for(x=-3;x<12;x++) {
            best=0x7FFFFFFFL;
            for(k=0u;k+1u<p->n;k++) { d=Stroke_Dist8(x*8,y*8,&p->p[k],&p->p[k+1u]); if(d<best) { best=d; } }
            if(best<=225 && (best>=81 || best<=9)) { s_hOn[slot][y+2] |= 1uL<<(x+3); }
        }
    }
}
static int32_t Stroke_RotX(int32_t x,int32_t y)
{
    return (x*SCENE_COS+y*SCENE_SIN)>>8;
}
static int32_t Stroke_RotY(int32_t x,int32_t y)
{
    return (-x*SCENE_SIN+y*SCENE_COS)>>8;
}
static uint8_t Stroke_PositionClear(int32_t cx,int32_t cy)
{
    int32_t slot,y,x,lx,ly,rx,ry,px,py,nx,ny;
    uint32_t mask,bit;
#if defined(FW_SIMULATOR)
    s_hourClearTests++;
#endif
    for(slot=0;slot<2;slot++) {
        for(y=-2;y<16;y++) {
            mask=s_hOn[slot][y+2];
            if(!mask) { continue; }
            for(x=-3;x<12;x++) {
                bit=1uL<<(x+3);
                if(mask&bit) {
                    lx=-12+slot*15+x; ly=-7+y;
                    rx=Stroke_RotX(lx,ly); ry=Stroke_RotY(lx,ly);
                    for(ny=-1;ny<=1;ny++) {
                        py=cy+ry+ny;
                        if((uint32_t)py>=OLED_H) { return 0u; }
                        for(nx=-1;nx<=1;nx++) {
                            px=cx+rx+nx;
                            if((uint32_t)px>=OLED_W) { return 0u; }
                            if(OLED_GRAM[py>>3][px]&(uint8_t)(1u<<(py&7))) { return 0u; }
                        }
                    }
                }
            }
        }
    }
    return 1u;
}
static uint8_t Stroke_FindSafe(int32_t prefX,int32_t prefY,int32_t *outX,int32_t *outY)
{
    int32_t r,dx,dy,cx,cy,score,bestScore,bestX,bestY,tdx,tdy,pdx,pdy,oldRadius,searchX,searchY,maxRadius;
    uint8_t found,usePrev,searchFromPrev,pass,passCount;
    usePrev=(uint8_t)(s_hourPosValid && Stroke_PositionClear(s_hourX,s_hourY));
    searchFromPrev=(uint8_t)(s_hourPosValid && !usePrev);
    searchX=searchFromPrev?s_hourX:prefX; searchY=searchFromPrev?s_hourY:prefY;
    bestX=searchX; bestY=searchY; s_hourLastRadius=0u;
    passCount=searchFromPrev?2u:1u;
    found=0u;
    for(pass=0u;pass<passCount;pass++) {
        if(pass>0u) { searchX=prefX; searchY=prefY; usePrev=0u; }
        maxRadius=(searchFromPrev && pass==0u)?6:64;
        for(r=0;r<=maxRadius;r++) {
            found=0u; bestScore=0x7FFFFFFFL;
            if(r==0) {
                cx=searchX; cy=searchY;
                if(Stroke_PositionClear(cx,cy)) {
                    tdx=cx-searchX; tdy=cy-searchY; score=tdx*tdx+tdy*tdy;
                    if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score=score*8+pdx*pdx+pdy*pdy; }
                    bestScore=score; bestX=cx; bestY=cy; found=1u;
                }
            } else {
                for(dx=-r;dx<=r;dx++) {
                    cx=searchX+dx; cy=searchY-r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                    cy=searchY+r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                }
                for(dy=-r+1;dy<r;dy++) {
                    cy=searchY+dy; cx=searchX-r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                    cx=searchX+r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                }
            }
            if(found) { s_hourLastRadius=(uint8_t)r; break; }
        }
        if(found) { break; }
    }
    if(!found) { return 0u; }
    if(usePrev) {
        dx=s_hourX-prefX; if(dx<0) { dx=-dx; }
        dy=s_hourY-prefY; if(dy<0) { dy=-dy; }
        oldRadius=(dx>dy)?dx:dy;
        if(oldRadius<=(int32_t)s_hourLastRadius+2) { bestX=s_hourX; bestY=s_hourY; }
    }
    *outX=bestX; *outY=bestY;
    return 1u;
}
static void Stroke_DrawAt(int32_t cx,int32_t cy)
{
    uint8_t slot;
    int32_t y,x,lx,ly,rx,ry;
    uint32_t mask,bit;
    for(slot=0u;slot<2u;slot++) {
        for(y=-2;y<16;y++) {
            mask=s_hOn[slot][y+2];
            if(!mask) { continue; }
            for(x=-3;x<12;x++) {
                bit=1uL<<(x+3);
                if(mask&bit) {
                    lx=-12+(int32_t)slot*15+x; ly=-7+y;
                    rx=Stroke_RotX(lx,ly); ry=Stroke_RotY(lx,ly);
                    OLED_DrawPixel(cx+rx,cy+ry,OLED_WHITE);
                }
            }
        }
    }
}
void Scene_DrawStrokeNum(int32_t cx,int32_t cy,uint8_t v,uint32_t nowMs)
{
    uint8_t w[2],i,canDraw,canMove;
    int32_t dx,dy,sx,sy,nx,ny,tx,ty,curDist,moveDist,bestMoveDist,fromX,fromY;
#if defined(FW_SIMULATOR)
    int32_t x,y;   /* only the simulator's frame snapshot walks the buffer */
#endif
    s_hourLastDrawn=0u;
    w[0]=(uint8_t)(v/10u); w[1]=(uint8_t)(v%10u);
    for(i=0u;i<2u;i++) { if(s_hv[i]!=w[i]) { Stroke_Build(i,w[i]); s_hv[i]=w[i]; } }
    if(!Stroke_FindSafe(cx,cy,&tx,&ty)) { return; }
    canDraw=(uint8_t)(s_hourPosValid && Stroke_PositionClear(s_hourX,s_hourY));
    canMove=(uint8_t)(!s_hourMoveClockValid || (uint32_t)(nowMs-s_hourMoveAt)>=HOUR_MOVE_INTERVAL_MS);
    if(!canDraw) {
        /* A moving hand/ring reached the old glyph: relocate immediately, never overlap. */
        s_hourX=(int16_t)tx; s_hourY=(int16_t)ty; s_hourPosValid=1u;
        s_hourMoveAt=nowMs; s_hourMoveClockValid=1u;
    } else if((tx!=s_hourX || ty!=s_hourY) && canMove) {
        fromX=s_hourX; fromY=s_hourY;
        dx=tx-s_hourX; dy=ty-s_hourY;
        sx=(dx>0)?1:((dx<0)?-1:0); sy=(dy>0)?1:((dy<0)?-1:0);
        curDist=dx*dx+dy*dy; bestMoveDist=curDist;
        nx=s_hourX+sx; ny=s_hourY+sy;
        if((sx || sy) && Stroke_PositionClear(nx,ny)) { moveDist=(tx-nx)*(tx-nx)+(ty-ny)*(ty-ny); if(moveDist<bestMoveDist) { bestMoveDist=moveDist; s_hourX=(int16_t)nx; s_hourY=(int16_t)ny; } }
        if(bestMoveDist==curDist && sx) {
            nx=s_hourX+sx; ny=s_hourY;
            if(Stroke_PositionClear(nx,ny)) { moveDist=(tx-nx)*(tx-nx)+(ty-ny)*(ty-ny); if(moveDist<bestMoveDist) { bestMoveDist=moveDist; s_hourX=(int16_t)nx; s_hourY=(int16_t)ny; } }
        }
        if(bestMoveDist==curDist && sy) {
            nx=s_hourX; ny=s_hourY+sy;
            if(Stroke_PositionClear(nx,ny)) { moveDist=(tx-nx)*(tx-nx)+(ty-ny)*(ty-ny); if(moveDist<bestMoveDist) { bestMoveDist=moveDist; s_hourX=(int16_t)nx; s_hourY=(int16_t)ny; } }
        }
        if(s_hourX!=fromX || s_hourY!=fromY) { s_hourMoveAt=nowMs; s_hourMoveClockValid=1u; }
    }
    if(Stroke_PositionClear(s_hourX,s_hourY)) {
#if defined(FW_SIMULATOR)
        for(y=0;y<OLED_H/8;y++) { for(x=0;x<OLED_W;x++) { s_hourBase[y][x]=OLED_GRAM[y][x]; } }
#endif
        Stroke_DrawAt(s_hourX,s_hourY);
        s_hourLastDrawn=1u;
    }
}
#if defined(FW_SIMULATOR)
__attribute__((export_name("fw_hour_info"))) uint32_t Scene_DebugHourInfo(void)
{
    return ((uint32_t)(uint8_t)s_hourX) | ((uint32_t)(uint8_t)s_hourY<<8) |
           ((uint32_t)s_hourLastDrawn<<16) | ((uint32_t)(s_hourLastRadius&0x7Fu)<<17);
}
__attribute__((export_name("fw_hour_checks"))) uint32_t Scene_DebugHourChecks(void) { return s_hourClearTests; }
__attribute__((export_name("fw_hour_base_ptr"))) uint32_t Scene_DebugHourBasePtr(void) { return (uint32_t)(uintptr_t)&s_hourBase[0][0]; }
#endif
static uint8_t Background(int32_t u,int32_t v,uint32_t q,int32_t phase)
{
    int32_t base,band,light=0,ad,tail;
    if(q>=65536u && q<196608u) {
        if(q<71536u) { light=255; } else {
            base=170-(int32_t)((q-65536u)*140u/131072u); band=((int32_t)OLED_Isqrt(q)+((u*v)>>7)-phase)&31;
            light=(band<5)?base+55:base/3;
        }
    }
    if(u<0 && u>-80) {
        ad=(v-8)*8; if(ad<0) { ad=-ad; }
        if(ad<18) { tail=220*(18-ad)*(80+u)/1440; if(((u-phase)&15)>3) { tail=tail*3/4; } if(tail>light) { light=tail; } }
    }
    return (uint8_t)light;
}
static uint8_t Fmt_Temp(char *b,int16_t t,uint8_t valid)
{
    uint8_t n=0u;
    int32_t v=t;
    uint32_t ip;
    if(!valid || v < -550 || v > 1250) { b[0]='-'; b[1]='-'; b[2]='.'; b[3]='-'; b[4]=0; return 4u; }
    if(v<0) { b[n++]='-'; v=-v; } ip=(uint32_t)(v/10);
    if(ip>=100u) { b[n++]=(char)('0'+(ip/100u)%10u); } if(ip>=10u) { b[n++]=(char)('0'+(ip/10u)%10u); }
    b[n++]=(char)('0'+ip%10u); b[n++]='.'; b[n++]=(char)('0'+v%10); b[n]=0; return n;
}
static void DrawInfo(const SceneInfo *info)
{
    char b[8];
    uint8_t n;
    uint16_t y;
    if(!info) { return; } OLED_FillRect(0,0,SCENE_INFO_W,SCENE_INFO_H,OLED_BLACK); y=info->year;
    b[0]=(char)('0'+(y/1000u)%10u); b[1]=(char)('0'+(y/100u)%10u); b[2]=(char)('0'+(y/10u)%10u); b[3]=(char)('0'+y%10u); b[4]=0;
    OLED_ShowString(2,3,b,OLED_WHITE);
    b[0]=(char)('0'+info->month/10u); b[1]=(char)('0'+info->month%10u); b[2]='.'; b[3]=(char)('0'+info->day/10u); b[4]=(char)('0'+info->day%10u); b[5]=0;
    OLED_ShowString(2,13,b,OLED_WHITE); OLED_FillRect(2,24,25,9,OLED_WHITE); OLED_ShowString(6,25,s_week[info->weekday%7u],OLED_BLACK);
    OLED_DrawHLine(2,36,29,OLED_WHITE); n=Fmt_Temp(b,info->tempTenths,info->tempValid);
    OLED_ShowString(2,39,b,OLED_WHITE); OLED_DrawRect(2+6*(int32_t)n,39,3,3,OLED_WHITE); OLED_ShowChar(6+6*(int32_t)n,39,'C',OLED_WHITE);
}
void Scene_BlackHole(uint32_t tMs,uint32_t msOfDay,const SceneInfo *info)
{
    int32_t x,y,dx,dy,u,v,un,vn,pixel,c,gx,gy,phase;
    uint32_t q;
    uint8_t hh=(uint8_t)((msOfDay/3600000u)%24u),mm=(uint8_t)((msOfDay/60000u)%60u),ss=(uint8_t)((msOfDay/1000u)%60u),light,threshold,sd;
    phase=(int32_t)((tMs/40u)&31u); Digits_Update(hh,mm); OLED_Clear();
    for(y=0;y<64;y++) { for(x=0;x<128;x++) {
        dx=x-SCENE_CX; dy=y-SCENE_CY; u=(dx*SCENE_COS-dy*SCENE_SIN)>>8; v=(dx*SCENE_SIN+dy*SCENE_COS)>>8;
        un=u*8; vn=v*10; q=(uint32_t)(un*un+vn*vn); light=TimeArea(u,v)?0u:Background(u,v,q,phase);
        threshold=(uint8_t)(s_bayer[((y&3)<<2)|(x&3)]*16u+8u); pixel=(light>threshold)?1:0;
        c=DigitPixel(0u,u-SCENE_HOUR_X,v-SCENE_HOUR_Y); if(c>=0) { pixel=c; }
        c=DigitPixel(1u,u-SCENE_HOUR_X-SCENE_DIG_PITCH,v-SCENE_HOUR_Y); if(c>=0) { pixel=c; }
        c=DigitPixel(2u,u-SCENE_MIN_X,v-SCENE_MIN_Y); if(c>=0) { pixel=c; }
        c=DigitPixel(3u,u-SCENE_MIN_X-SCENE_DIG_PITCH,v-SCENE_MIN_Y); if(c>=0) { pixel=c; }
        gx=u-SCENE_SEC_X; gy=v-SCENE_SEC_Y;
        if(gx>=0 && gx<12 && gy>=0 && gy<7) { sd=(uint8_t)((gx<6)?ss/10u:ss%10u); pixel=(gx%6<5)?((s_small[sd][gx%6]>>gy)&1u):0; }
        if(pixel) { OLED_DrawPixel(x,y,OLED_WHITE); }
    } }
    for(c=0;c<4;c++) { OLED_DrawPixel(s_star[c][0],s_star[c][1],OLED_WHITE); } DrawInfo(info);
}
/* ===========================================================================
 * V20 countdown panel  ("铃声界面")  --  password-lock (drum) style
 * ---------------------------------------------------------------------------
 * Layout: black background, white 1-pixel drawing only.
 *
 *      ┌───────────┐   ┌───────────┐   ┌───────────┐   ┌─────────────┐
 *      │    0 9    │   │    5 8    │   │    3 4    │   │             │
 *      │   1 0     │ : │   5 9     │ : │   3 5     │   │    Start    │
 *      │    1 1    │   │    0 0    │   │    3 6    │   │             │
 *      └───────────┘   └───────────┘   └───────────┘   └─────────────┘
 *         时 00-99         分 00-59         秒 00-59       Start / %
 *                                                       23:59 <- live clock
 *
 *  - the middle row is the value being edited (large digit), the rows above and
 *    below show the neighbouring values (small digits) exactly like a
 *    combination lock / drum; they wrap (59 -> 00) together with the carries
 *  - a value change rolls the drum for PN_ROLL_MS; the digits slide and the one
 *    reaching the centre grows, so the panel feels like a real picker
 *  - the four frames are all exactly the same height and aligned; the selected
 *    frame blinks, the digits inside never blink
 *  - the digits are drawn from one CONNECTED stroke font (2 px round strokes
 *    for the middle row, 1 px for the small rows): no stroke of any digit is
 *    ever broken - there is a self test that checks every digit is a single
 *    connected shape at both sizes
 *  - nothing but "Start" is written on the screen (plus the small live clock)
 * =========================================================================== */
#define PN_BOX_Y0    12                 /* frames: y = 12..59, all four equal */
#define PN_BOX_Y1    59
#define PN_BOX_H     (PN_BOX_Y1-PN_BOX_Y0+1)     /* 48 */
#define PN_BOX_W     25                 /* number frame width                */
#define PN_BOX_B1    1                  /* hour   frame  x = 1..25           */
#define PN_BOX_B2    32                 /* minute frame  x = 32..56          */
#define PN_BOX_B3    63                 /* second frame  x = 63..87          */
#define PN_BOX_B4    94                 /* Start  frame  x = 94..126         */
#define PN_BOX_B4W   33
#define PN_RADIUS    7                  /* obtuse (rounded) corners          */
#define PN_CY0       19                 /* drum row centres: 19 / 36 / 53    */
#define PN_CY1       36
#define PN_CY2       53
#define PN_PITCH     17                 /* row pitch = 17 px (drum geometry) */
#define PN_BLINK_MS  400u               /* selected-frame blink half period  */
#define PN_ROLL_MS   140u               /* drum roll duration after a change */
#define PN_BAR_Y     61                 /* progress bar (running view)       */
#define PN_BAR_X0    2
#define PN_BAR_X1    125

/* ---------------- connected stroke digit font ------------------------------
 * Glyph space: x = 0..20, y = 0..40 in HALF pixels (a 10x20 px cell at scale
 * 1). Every digit is defined by polylines; a digit made of two polylines has
 * them crossing, so the rendered ink is one single connected shape. Zooming to
 * the small rows is a 0.5 coordinate scale plus a pixel-centre snap, which
 * keeps the 1 px strokes crisp and still connected. */
typedef struct { int8_t x,y; } PanelPt;
typedef struct { const PanelPt *p; uint8_t n; } PanelPath;
typedef struct { const PanelPath *paths; uint8_t n; } PanelGlyph;

static const PanelPt pnP0[] = {{2,6},{6,2},{14,2},{18,6},{18,34},{14,38},{6,38},{2,34},{2,6}};
static const PanelPt pnP1a[] = {{8,6},{14,2},{14,38}};
static const PanelPt pnP1b[] = {{6,38},{18,38}};
static const PanelPt pnP2[] = {{2,6},{6,2},{14,2},{18,6},{18,13},{3,38},{18,38}};
static const PanelPt pnP3[] = {{3,3},{7,2},{13,2},{18,7},{18,13},{11,19},{10,20},{11,21},{18,27},{18,33},{13,38},{7,38},{2,36}};
static const PanelPt pnP4a[] = {{13,2},{2,25},{18,25}};
static const PanelPt pnP4b[] = {{13,2},{13,38}};
static const PanelPt pnP5[] = {{18,2},{2,2},{2,17},{12,13},{18,18},{18,34},{13,38},{6,38},{2,35}};
static const PanelPt pnP6[] = {{15,2},{6,3},{2,10},{2,32},{6,38},{13,38},{18,32},{18,26},{13,21},{7,21},{2,26}};
static const PanelPt pnP7[] = {{2,2},{18,2},{7,38}};
static const PanelPt pnP8a[] = {{6,2},{14,2},{18,6},{18,14},{14,20},{6,20},{2,14},{2,6},{6,2}};
static const PanelPt pnP8b[] = {{6,20},{14,20},{18,26},{18,34},{14,38},{6,38},{2,34},{2,26},{6,20}};
static const PanelPt pnP9[] = {{5,38},{12,37},{18,30},{18,8},{14,2},{7,2},{2,7},{2,14},{6,20},{12,20},{18,15}};

static const PanelPath pnG0[1]={{pnP0,9}};
static const PanelPath pnG1[2]={{pnP1a,3},{pnP1b,2}};
static const PanelPath pnG2[1]={{pnP2,7}};
static const PanelPath pnG3[1]={{pnP3,13}};
static const PanelPath pnG4[2]={{pnP4a,3},{pnP4b,2}};
static const PanelPath pnG5[1]={{pnP5,9}};
static const PanelPath pnG6[1]={{pnP6,11}};
static const PanelPath pnG7[1]={{pnP7,3}};
static const PanelPath pnG8[2]={{pnP8a,9},{pnP8b,9}};
static const PanelPath pnG9[1]={{pnP9,11}};
static const PanelGlyph s_pnGlyph[10]={
    {pnG0,1},{pnG1,2},{pnG2,1},{pnG3,1},{pnG4,2},{pnG5,1},{pnG6,1},{pnG7,1},{pnG8,2},{pnG9,1}
};
/* One glyph. ox/oy = top-left corner of the digit cell in screen pixels.
 * small=0: 10x20 px cell, 2 px round strokes.
 * small=1: 6x11 px cell, 1 px strokes snapped to the pixel centres. */
static void Panel_Glyph(int32_t ox,int32_t oy,uint8_t d,uint8_t small)
{
    const PanelGlyph *g;
    uint8_t pi,k;
    if(d>9u) { return; }
    g=&s_pnGlyph[d];
    for(pi=0u;pi<g->n;pi++) {
        const PanelPath *p=&g->paths[pi];
        for(k=0u;k+1u<p->n;k++) {
            int32_t x0,y0,x1,y1,r;
            if(!small) {
                x0=ox*256+(int32_t)p->p[k].x*128;   y0=oy*256+(int32_t)p->p[k].y*128;
                x1=ox*256+(int32_t)p->p[k+1].x*128; y1=oy*256+(int32_t)p->p[k+1].y*128;
                r=128;
            } else {
                /* half scale: 5 px wide, 9 px tall; the vertical map is slightly
                 * compressed so the small rows keep a 2 px air gap to the large
                 * digits above and below them */
                x0=(ox+(((int32_t)p->p[k].x+2)>>2))*256+128;         y0=(oy+1+(((int32_t)p->p[k].y*7+16)>>5))*256+128;
                x1=(ox+(((int32_t)p->p[k+1].x+2)>>2))*256+128;       y1=(oy+1+(((int32_t)p->p[k+1].y*7+16)>>5))*256+128;
                r=0;
            }
            OLED_DrawBrushSegQ8(x0,y0,r,x1,y1,r,OLED_WHITE);
        }
    }
}
/* One drum row: the two digits of a value, centred in the frame. */
static void Panel_Row(int32_t fx0,int32_t fw,int32_t cy,uint8_t v,uint8_t small)
{
    int32_t inner_x=fx0+2,inner_w=fw-4,ox;
    if(v>99u) { v=99u; }
    if(!small) {
        ox=inner_x+(inner_w-21)/2;
        Panel_Glyph(ox,cy-10,(uint8_t)(v/10u),0u);
        Panel_Glyph(ox+11,cy-10,(uint8_t)(v%10u),0u);
    } else {
        ox=inner_x+(inner_w-13)/2;
        Panel_Glyph(ox,cy-5,(uint8_t)(v/10u),1u);
        Panel_Glyph(ox+7,cy-5,(uint8_t)(v%10u),1u);
    }
}
/* ---------------- frames / clock / text ---------------------------------- */
static void Panel_BoxFrame(uint8_t idx,uint8_t selected,uint8_t blinkOn)
{
    int32_t x0,w;
    if(idx==0u) { x0=PN_BOX_B1; w=PN_BOX_W; }
    else if(idx==1u) { x0=PN_BOX_B2; w=PN_BOX_W; }
    else if(idx==2u) { x0=PN_BOX_B3; w=PN_BOX_W; }
    else { x0=PN_BOX_B4; w=PN_BOX_B4W; }
    if(!selected || blinkOn) { OLED_DrawRoundRect(x0,PN_BOX_Y0,x0+w-1,PN_BOX_Y1,PN_RADIUS,OLED_WHITE); }
}
static void Panel_Colons(void)
{
    OLED_FillRect(28,30,2,2,OLED_WHITE); OLED_FillRect(28,40,2,2,OLED_WHITE);
    OLED_FillRect(59,30,2,2,OLED_WHITE); OLED_FillRect(59,40,2,2,OLED_WHITE);
}
/* small live clock, right aligned in the top right corner ("HH:MM") */
static void Panel_Clock(uint32_t msOfDay)
{
    char b[6];
    uint8_t hh=(uint8_t)((msOfDay/3600000u)%24u),mm=(uint8_t)((msOfDay/60000u)%60u);
    b[0]=(char)('0'+hh/10u); b[1]=(char)('0'+hh%10u); b[2]=':';
    b[3]=(char)('0'+mm/10u); b[4]=(char)('0'+mm%10u); b[5]=0;
    OLED_ShowString(98,1,b,OLED_WHITE);
}
static void Panel_Base(uint32_t msOfDay) { OLED_Clear(); Panel_Clock(msOfDay); Panel_Colons(); }
static void Panel_CentreText(int32_t x0,int32_t w,const char *t)
{
    int32_t n=0;
    while(t[n]) { n++; }
    OLED_ShowString(x0+(w-(n*6-1))/2,PN_BOX_Y0+(PN_BOX_H-8)/2,t,OLED_WHITE);
}
/* ---------------- drum state (self-contained in Scene.c) ------------------ */
static uint8_t s_pnPrev[3]={0xFFu,0xFFu,0xFFu};
static uint8_t s_pnDir[3]={0u,0u,0u};
static uint32_t s_pnRollAt[3]={0u,0u,0u};
/* Wrap around the field range: hour 0..99, minute/second 0..59. */
static uint8_t Panel_Wrap(uint8_t field,int32_t v)
{
    int32_t lo=(field==0u)?100:60;
    v%=lo; if(v<0) { v+=lo; }
    return (uint8_t)v;
}
/* Draw the drum of one number frame: the value `v` sits in the middle row, the
 * neighbours above/below are the small candidates, and while a change is being
 * animated every row slides by the same amount (clipped to the frame). */
static void Panel_Drum(int32_t fx0,uint8_t fw,uint8_t field,uint32_t tMs,uint8_t v,uint8_t selected,uint8_t blinkOn)
{
    int32_t i,j,off=0,n=0;
    int32_t ys[4],ad[4],order[4];
    uint8_t ws[4];
    uint32_t el;
    if(s_pnPrev[field]!=v) {
        if(s_pnPrev[field]==0xFFu) { s_pnDir[field]=0u; }
        else {
            int32_t lo=(field==0u)?100:60;
            int32_t d=(int32_t)v-(int32_t)s_pnPrev[field];
            if(d<0) { d+=lo; }
            /* d==0 cannot happen here; small d = value grew, large d = shrank */
            s_pnDir[field]=(uint8_t)((d*2<=lo)?1u:2u);
        }
        s_pnPrev[field]=v; s_pnRollAt[field]=tMs+1u;
    }
    if(s_pnRollAt[field]!=0u) {
        el=(uint32_t)(tMs-(s_pnRollAt[field]-1u));
        if(el>=PN_ROLL_MS) { s_pnRollAt[field]=0u; }
        else { off=(int32_t)(PN_PITCH*(PN_ROLL_MS-el)/PN_ROLL_MS); }
    }
    Panel_BoxFrame(field,selected,blinkOn);
    OLED_SetClipRect(fx0+1,PN_BOX_Y0+1,fx0+(int32_t)fw-2,PN_BOX_Y1-1);
    if(off==0) {
        /* settled: neighbours above/below are the candidate values */
        Panel_Row(fx0,fw,PN_CY0,Panel_Wrap(field,(int32_t)v-1),1u);
        Panel_Row(fx0,fw,PN_CY2,Panel_Wrap(field,(int32_t)v+1),1u);
        Panel_Row(fx0,fw,PN_CY1,v,0u);
    } else {
        /* rolling: every row slides by the same amount; the row that reaches
         * the centre becomes the large one, so the value appears to grow */
        if(s_pnDir[field]==1u) {
            for(i=0;i<4;i++) {
                int32_t w=(int32_t)v-2+i;
                ws[n]=Panel_Wrap(field,w);
                ys[n]=PN_CY1+(w-(int32_t)v)*PN_PITCH+off;
                n++;
            }
        } else {
            for(i=0;i<4;i++) {
                int32_t w=(int32_t)v-1+i;
                ws[n]=Panel_Wrap(field,w);
                ys[n]=PN_CY1+(w-(int32_t)v)*PN_PITCH-off;
                n++;
            }
        }
        for(i=0;i<n;i++) { ad[i]=ys[i]-PN_CY1; if(ad[i]<0) { ad[i]=-ad[i]; } }
        for(i=0;i<n;i++) {
            int32_t best=-1;
            for(j=0;j<n;j++) { if(ad[j]<0) { continue; } if(best<0 || ad[j]>ad[best]) { best=j; } }
            order[i]=best; ad[best]=-1;
        }
        for(i=0;i<n;i++) {
            int32_t d=ys[order[i]]-PN_CY1;
            if(d<0) { d=-d; }
            Panel_Row(fx0,fw,ys[order[i]],ws[order[i]],(uint8_t)((d*2>=PN_PITCH)?1u:0u));
        }
    }
    OLED_SetClipRect(0,0,-1,-1);
}
/* Snap all three drums (no roll) - called when the panel is (re)entered so the
 * first drawn frame is always the settled state. */
void Scene_TimerPanelReset(void)
{
    s_pnPrev[0]=0xFFu; s_pnPrev[1]=0xFFu; s_pnPrev[2]=0xFFu;
    s_pnDir[0]=0u; s_pnDir[1]=0u; s_pnDir[2]=0u;
    s_pnRollAt[0]=0u; s_pnRollAt[1]=0u; s_pnRollAt[2]=0u;
}
/* ---------------- public API -------------------------------------------- */
/* Setup screen: 时/分/秒 drums + Start, small live clock, nothing else. */
void Scene_TimerPanel(uint32_t tMs,uint32_t msOfDay,uint8_t h,uint8_t m,uint8_t s,uint8_t selected)
{
    uint8_t blinkOn=(uint8_t)(((tMs/PN_BLINK_MS)&1u)==0u);
    Panel_Base(msOfDay);
    Panel_Drum(PN_BOX_B1,PN_BOX_W,0u,tMs,h,(uint8_t)(selected==0u),blinkOn);
    Panel_Drum(PN_BOX_B2,PN_BOX_W,1u,tMs,m,(uint8_t)(selected==1u),blinkOn);
    Panel_Drum(PN_BOX_B3,PN_BOX_W,2u,tMs,s,(uint8_t)(selected==2u),blinkOn);
    Panel_BoxFrame(3u,(uint8_t)(selected==3u),blinkOn);
    Panel_CentreText(PN_BOX_B4,PN_BOX_B4W,"Start");
}
/* Running screen: remaining time (large digits, no drum), remaining percentage
 * in the 4th frame and a 1 px progress bar below the frames. */
void Scene_TimerRunning(uint32_t msOfDay,uint32_t remainMs,uint32_t pct)
{
    char b[5];
    uint8_t hh=(uint8_t)(remainMs/3600000u),mm=(uint8_t)((remainMs/60000u)%60u),ss=(uint8_t)((remainMs/1000u)%60u);
    uint32_t left,w;
    int32_t x;
    if(hh>99u) { hh=99u; }
    if(pct>1000u) { pct=1000u; }
    left=(1000u-pct+5u)/10u;
    Panel_Base(msOfDay);
    Panel_BoxFrame(0u,0u,1u); Panel_BoxFrame(1u,0u,1u); Panel_BoxFrame(2u,0u,1u); Panel_BoxFrame(3u,0u,1u);
    Panel_Row(PN_BOX_B1,PN_BOX_W,PN_CY1,hh,0u);
    Panel_Row(PN_BOX_B2,PN_BOX_W,PN_CY1,mm,0u);
    Panel_Row(PN_BOX_B3,PN_BOX_W,PN_CY1,ss,0u);
    if(left>=100u) { b[0]='1'; b[1]='0'; b[2]='0'; b[3]='%'; b[4]=0; }
    else if(left>=10u) { b[0]=(char)('0'+left/10u); b[1]=(char)('0'+left%10u); b[2]='%'; b[3]=0; }
    else { b[0]=(char)('0'+left); b[1]='%'; b[2]=0; }
    Panel_CentreText(PN_BOX_B4,PN_BOX_B4W,b);
    for(x=PN_BAR_X0;x<=PN_BAR_X1;x+=4) { OLED_DrawPixel(x,PN_BAR_Y,OLED_WHITE); }
    w=(uint32_t)(pct*(uint32_t)(PN_BAR_X1-PN_BAR_X0)/1000u);
    if(w>0u) { OLED_DrawHLine(PN_BAR_X0,PN_BAR_Y,(int32_t)w,OLED_WHITE); }
}

void Scene_Compose(uint8_t a[8][128],uint8_t b[8][128],uint16_t p)
{
    int32_t x,y,dx,dy,d2,R,fn,fo,sx,sy,bit,idx,m;
    if(p>256u) { p=256u; } R=((int32_t)p*80)>>8; fn=1024-3*(int32_t)p; fo=256-((3*(int32_t)p)>>2);
    for(y=0;y<64;y++) { for(x=0;x<128;x++) {
        dx=x-64; dy=y-32; d2=dx*dx+dy*dy;
        if(d2<R*R) { sx=64+((dx*fn)>>8); sy=32+((dy*fn)>>8); } else { sx=64+((dx*fo)>>8); sy=32+((dy*fo)>>8); }
        if(sx<0 || sx>=128 || sy<0 || sy>=64) { bit=0; } else if(d2<R*R) { bit=(b[sy>>3][sx]>>(sy&7))&1; } else { bit=(a[sy>>3][sx]>>(sy&7))&1; }
        if(R>=2 && d2>=(R-1)*(R-1) && d2<(R+1)*(R+1)) { bit=1; } idx=y>>3; m=1<<(y&7);
        if(bit) { OLED_GRAM[idx][x] |= (uint8_t)m; } else { OLED_GRAM[idx][x] &= (uint8_t)~m; }
    } }
}
